if(o.kind==='tip'){const rem=sum(o.sources.map(atWorker));return productUI()+tipSources()+(o.sources.filter(r=>atWorker(r)>0).length>1?det('本次打头来源批次',o.sources.filter(r=>atWorker(r)>0).map(r=>btn(r.id+' · '+qt(atWorker(r),r.unit),'source:'+r.id,'choose-row '+(v('source')===r.id?'selected':''))).join('')):'')+(rem>0?F('qty','本批打头',o.ou)+F('length','实际成品长度','mm')+det('实际两端做法',`<label class="label">端 A</label><div class="asa-options">${['包头','浸头','无'].map(x=>btn(x,'endA:'+x,(v('endA')|| (o.tipMode==='cap'?'包头':'浸头'))===x?'choice selected':'choice')).join('')}</div><label class="label">端 B</label><div class="asa-options">${['包头','浸头','无'].map(x=>btn(x,'endB:'+x,(v('endB')||(o.ends===1?'无':o.tipMode==='cap'?'包头':'浸头'))===x?'choice selected':'choice')).join('')}</div>`)+materialSummary()+F('material','本批实际耗用辅材',o.materials[0].unit)+det('不良 / 辅材损耗',F('bad','其中不良',o.ou,'未发生留空')+F('matLoss','辅材损耗',o.materials[0].unit,'未发生留空')+F('reason','不良或损耗原因')):'' );}
