function outgoingPreview(b){const rows=b.skus?b.skus.map(r=>({qty:v('out-'+b.id+'-'+r.part)===''?r.qty-(r.sent||0):n('out-'+b.id+'-'+r.part),max:r.qty-(r.sent||0)})):[{qty:v('out-'+b.id)===''?q(b.good-b.sent):n('out-'+b.id),max:q(b.good-b.sent)}];const qty=sum(rows.map(r=>r.qty));return {qty,valid:qty>0&&rows.every(r=>Number.isFinite(r.qty)&&r.qty>=0&&r.qty<=r.max&&Math.abs(r.qty*1000-Math.round(r.qty*1000))<1e-6&&(!int(O().ou)||Number.isSafeInteger(r.qty)))};}
