function packageAction(b){const selected=selectedPackage();if(selected){if(!selected.sent)return ['交出 '+selected.id+' · '+qt(selected.qty),'package-send:'+selected.id,'worker'];return null;}const pending=(b.packages||[]).filter(p=>!p.sent),left=q(b.good-sum((b.packages||[]).map(p=>p.qty))),key='packQty-'+b.id;if(left>0&&(v(key)!==''||!pending.length)){const x=n(key),valid=Number.isSafeInteger(x)&&x>0&&x<=left;return [v(key)===''?'装包并生成包码':valid?'确认装包 '+qt(x):'核对本包数量','package:'+b.id,'worker'];}if(pending.length===1)return ['交出 '+pending[0].id+' · '+qt(pending[0].qty),'package-send:'+pending[0].id,'worker'];if(pending.length>1)return ['选择要交出的包','show-packages','worker'];return null;}
