function receipts(){const packageId=s.view==='out'?v('package'):s.view==='receipt'&&s.receiptOrder===s.order?s.receiptPackage:null,batchId=s.view==='out'?v('batch'):s.view==='receipt'&&s.receiptOrder===s.order?s.receiptBatch:null,all=s.hands.filter(h=>h.order===O().id),hs=all.filter(h=>(!batchId||h.batch===batchId)&&(!packageId||h.package===packageId));const more=(packageId&&all.some(h=>h.batch===batchId&&h.package!==packageId)?btn('查看本批全部实收','receipts-batch','quiet'):'')+(batchId&&all.some(h=>h.batch!==batchId)?btn('查看本单全部实收','receipts-all','quiet'):'');return hs.length?`<section class="asa-receipts" data-receipt-batch="${esc(batchId||'')}" data-receipt-package="${esc(packageId||'')}"><h3>${packageId?'本包交出与实收':batchId?'本批交出与实收':'本单交出与实收'}</h3>${hs.map(h=>panel(info(h.id,h.actual===null?'待点收':h.partial&&h.actual<h.qty?'部分实收':'已实收')+kv('来源批次',h.batch)+(h.package?kv('包码',h.package):'')+kv('交给',h.target)+`<div class="asa-numbers"><div><small>我方交出</small><b>${qt(h.qty,h.unit)}</b></div><div><small>对方实收</small><b>${h.actual===null?'待点收':qt(h.actual,h.unit)}</b></div></div>`+(h.actual!==null&&h.actual!==h.qty?note(h.partial&&h.actual<h.qty?'尚待实收 '+qt(q(h.qty-h.actual),h.unit):'本次实收 '+qt(h.actual,h.unit),h.partial&&h.actual<h.qty?'info':'warn'):'')+det('交接责任与明细',kv('来源批次',h.batch)+(h.dispatchReason?kv('退回原因',h.dispatchReason):'')+(h.sources||[]).map(r=>kv('原实物',r.id+' / '+r.doc+(r.qty!==null?' · '+qt(r.qty,r.unit):''))).join('')+kv('交出人',h.actor+' · '+h.time)+(h.skus?h.skus.map(r=>kv(r.part,qt(r.qty,h.unit)+' → '+(r.actual===undefined?'待点收':qt(r.actual,h.unit)))).join(''):'')+(h.receiver?kv('实收人',h.receiver)+kv('实际库位',h.loc)+kv('实收时间',h.receivedAt):'')+(h.logs||[]).map(r=>kv(r.time,qt(r.qty,h.unit)+' · '+r.actor+' · '+r.loc+(r.reason?' · '+r.reason:''))).join(''))+(!O().closed&&h.next?btn('查看下道接收','next:'+h.next,'choose-row'):''))).join('')}${more}</section>`:(batchId?note(packageId?'本包尚未交出。':'本批尚未交出。','info')+more:'');}
function stockUI(){const o=O();return productUI()+`<h3>${isSpecial(o)?'待加工仓':'本单实际来料'}</h3>`+o.sources.map(r=>panel(kv(r.id+' · '+r.part,qt(available(r),r.unit))+kv('来源 / 库位',r.doc+' / '+(r.loc||'待接收'))+kv('现场未用',qt(atWorker(r),r.unit))+(r.receiveEntries?.length>1?det('逐次实收',r.receiveEntries.map(x=>kv(x.time,qt(x.qty,r.unit)+' · '+x.actor+' / '+x.loc+' · '+x.reason)).join('')):'')+(pendingReceive(o,r)?btn('点收本次来货','source-receive:'+r.id,'choose-row'):''))).join('')+`<h3>${isSpecial(o)?'待交出仓':'本单实际产出'}</h3>`+o.batches.map(b=>panel(kv(b.id,qt(b.good-b.sent))+kv('状态',b.needsTip?(b.pendingTip?'待打头':'已转打头'):b.inbound?'已入仓':'待仓管点收')+kv('不良 / 损耗',qt(b.bad||0))+(b.bad?note('不良保留在本批，等待有权人员核对；不计可交量。'):'')+btn('查看本批交出','batch-out:'+b.id,'choose-row'))).join('')+receipts();}
