function action(){const o=O();if(o.closed)return null;if(s.view==='detail'&&hasReceipt(o))return ['加工填报','view:work','worker'];if(s.view==='receive'&&(o.kind==='lace'&&!o.accepted||o.sources.some(r=>pendingReceive(o,r))||o.kind==='tip'&&o.materials.some(m=>m.received<m.qty)))return ['确认接收','receive','store'];if(s.view==='work'&&hasReceipt(o))return ['保存加工填报','work','worker'];if(s.view==='finish'&&canFinish(o))return ['确认完工','finish-save','worker'];return null;}
